(33261, 'Psalms 7:11', 'Psalms', 7, 11, 'خدای دی عادل قاضي بدکاران هره ورځ غندي', 'خدای دی عادل قاضی بدکاران هره ورج غندی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33262, 'Psalms 7:12', 'Psalms', 7, 12, 'که دوی نه کړلې بدلې خپلې لارې خدای به تېره کړي ورته خپله توره هغه کشوي او تیاروي ورته لینده خپله', 'که دوی نه کرلې بدلې خپلې لارې خدای به تېره کری ورته خپله توره هغه کشوی او تیاروی ورته لینده خپله', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33263, 'Psalms 7:13', 'Psalms', 7, 13, 'کړي به وژونکې وسله ورته تیاره جوړوي ورته هم غشي سوځوونکي', 'کری به وژونکې وسله ورته تیاره جوروی ورته هم غشی سوجوونکی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33264, 'Psalms 7:14', 'Psalms', 7, 14, 'ګورئ څنګه کوي فکر د بدۍ دا بدکاران جوړوي د ځورولو پلانونه دروغ وایي', 'ګوری چنګه کوی فکر د بدی دا بدکاران جوروی د جورولو پلانونه دروغ وایی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33265, 'Psalms 7:15', 'Psalms', 7, 15, 'نورو خلکو ته چې دوی کیندي څاګانې شي به په خپله ورګوزار په کې', 'نورو خلکو ته چې دوی کیندی چاګانې شی به په خپله ورګوزار په کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33266, 'Psalms 7:16', 'Psalms', 7, 16, 'ومومي سزا د خپلو بدو به هغه ظلمونه به یې انبار شي په خپل سر باندې', 'ومومی سزا د خپلو بدو به هغه ظلمونه به یې انبار شی په خپل سر باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33267, 'Psalms 7:17', 'Psalms', 7, 17, 'شکر به وکړم له څښتنه د انصاف دپاره څښتن تعالی ته به ثنا وایمه په سندرو سره', 'شکر به وکرم له چشتنه د انصاف دپاره چشتن تعالی ته به ثنا وایمه په سندرو سره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_7_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33268, 'Psalms 96:1', 'Psalms', 96, 1, 'څښتن ته ووایئ یوه نوې سندره ای ټولې نړۍ، سندره ووایئ څښتن ته تاسې', 'چشتن ته ووایی یوه نوې سندره ای تولې نری، سندره ووایی چشتن ته تاسې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33269, 'Psalms 96:2', 'Psalms', 96, 2, 'څښتن ته ووایئ سندره او ستاینه یې د نوم وکړئ اعلان کړئ هره ورځ دا زېری چې نجات یې دی راکړی مونږ ته', 'چشتن ته ووایی سندره او ستاینه یې د نوم وکری اعلان کری هره ورج دا زېری چې نجات یې دی راکری مونز ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33270, 'Psalms 96:3', 'Psalms', 96, 3, 'قومونو ته اعلان کړئ جلال د هغه ټولو خلکو ته اعلان کړئ د هغه ډېر عجیبه کارونه', 'قومونو ته اعلان کری جلال د هغه تولو خلکو ته اعلان کری د هغه دېر عجیبه کارونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33271, 'Psalms 96:4', 'Psalms', 96, 4, 'ځکه چې لوی دی څښتن او ډېر لایق دی د ثنا او صفت ټولو خدایانو نه دې زیاته وېره وشي د ده', 'جکه چې لوی دی چشتن او دېر لایق دی د ثنا او صفت تولو خدایانو نه دې زیاته وېره وشی د ده', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33272, 'Psalms 96:5', 'Psalms', 96, 5, 'نورو قومونو ټول خدایان دي بې‌ګټې بتان خو څښتن دي پیدا کړي اسمانونه', 'نورو قومونو تول خدایان دی بې‌ګتې بتان خو چشتن دی پیدا کری اسمانونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33273, 'Psalms 96:6', 'Psalms', 96, 6, 'دی راچاپېره جلال او لویي له هغه څخه سپېڅلی کور د هغه ډک دی له قوت او ښایست', 'دی راچاپېره جلال او لویی له هغه چخه سپېچلی کور د هغه دک دی له قوت او شایست', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33274, 'Psalms 96:7', 'Psalms', 96, 7, 'وکړئ ستاینه د څښتن په ځمکه ټولو خلکو هم ستاینه وکړئ د هغه د جلال او قدرت', 'وکری ستاینه د چشتن په جمکه تولو خلکو هم ستاینه وکری د هغه د جلال او قدرت', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33275, 'Psalms 96:8', 'Psalms', 96, 8, 'د څښتن د جلالي نوم ستاینه وکړئ د هغه دربار ته راشئ او نذرانه راوړئ', 'د چشتن د جلالی نوم ستاینه وکری د هغه دربار ته راشی او نذرانه راوری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33276, 'Psalms 96:9', 'Psalms', 96, 9, 'کړئ څښتن ته عبادت په سپېڅلې توګه ای ټولې ځمکې ولړزېږه د هغه په مخکې', 'کری چشتن ته عبادت په سپېچلې توګه ای تولې جمکې ولرزېزه د هغه په مخکې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33277, 'Psalms 96:10', 'Psalms', 96, 10, 'تاسو خبر کړئ ټول قومونه د نړۍ چې دی څښتن پاچا! نړۍ یې ټینګه درولې چې خوځیږي نه او قضاوت به د قومونو کړي انصاف باندې', 'تاسو خبر کری تول قومونه د نری چې دی چشتن پاچا! نری یې تینګه درولې چې خوجیزی نه او قضاوت به د قومونو کری انصاف باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33278, 'Psalms 96:11', 'Psalms', 96, 11, 'پرېږده خوشحاله اسمانونه شي او ځمکه وکړي خوښي شي دریاب په غړمبار دې خپلو ټولو مخلوقاتو سره', 'پرېزده خوشحاله اسمانونه شی او جمکه وکری خوشی شی دریاب په غرمبار دې خپلو تولو مخلوقاتو سره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33279, 'Psalms 96:12', 'Psalms', 96, 12, 'شي دې خوشحاله پټي هم ټولو فصلونو سره د ځنګل ټولې ونې به بیا ووهي د خوشحالۍ چیغې', 'شی دې خوشحاله پتی هم تولو فصلونو سره د جنګل تولې ونې به بیا ووهی د خوشحالی چیغې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33280, 'Psalms 96:13', 'Psalms', 96, 13, 'کله چې راشي د ځمکې قضاوت ته څښتن نو په انصاف سره به وکړي قضاوت د نړۍ او قضاوت د ولسونو عدالت باندې', 'کله چې راشی د جمکې قضاوت ته چشتن نو په انصاف سره به وکری قضاوت د نری او قضاوت د ولسونو عدالت باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_96_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33281, 'Job 39:1', 'Job', 39, 1, 'تا ته پته شته چې کله د غرۀ چېلۍ بچى راوړى؟ ولې تۀ پرې نظر ساتې چې کله هوسۍ بچى راوړى؟', 'تا ته پته شته چې کله د غرۀ چېلی بچی راوری؟ ولې تۀ پرې نظر ساتې چې کله هوسی بچی راوری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33282, 'Job 39:2', 'Job', 39, 2, 'ولې تا ته پته شته چې دا بچى څو مياشتې د هغوئ په ګېډه وى؟ او تا ته د هغه وخت پته شته څۀ چې دا به کله پېدا شى', 'ولې تا ته پته شته چې دا بچی چو میاشتې د هغوی په ګېده وی؟ او تا ته د هغه وخت پته شته چۀ چې دا به کله پېدا شی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33283, 'Job 39:3', 'Job', 39, 3, 'کله چې هغوئ د اولاد د پېدا کېدو دپاره کښېنى، او د هغوئ بچى پېدا شى؟', 'کله چې هغوی د اولاد د پېدا کېدو دپاره کشېنی، او د هغوی بچی پېدا شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33284, 'Job 39:4', 'Job', 39, 4, 'د هغوئ بچى تکړه شى او په ځنګل کښې لوئيږى، هغوئ ترې نه لاړ شى او واپس ورله نۀ راځى.', 'د هغوی بچی تکره شی او په جنګل کشې لوییزی، هغوی ترې نه لار شی او واپس ورله نۀ راجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33285, 'Job 39:5', 'Job', 39, 5, 'ځنګلى خرونه چا پرېښې دى چې خوشى لاړ شى؟ دا چا آزاد پرېښى دى چې ګرځى راګرځى؟', 'جنګلی خرونه چا پرېشې دی چې خوشی لار شی؟ دا چا ازاد پرېشی دی چې ګرجی راګرجی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33286, 'Job 39:6', 'Job', 39, 6, 'ما دا په صحرا کښې پرېښى دى، او د مالګې مُلک مې ورکړے دے چې په کښې اوسيږى.', 'ما دا په صحرا کشې پرېشی دی، او د مالګې ملک مې ورکرے دے چې په کشې اوسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33287, 'Job 39:7', 'Job', 39, 7, 'هغه د ښار د شور نه نفرت کوى، او خرکار ورسره نشته چې په دې باندې آواز وکړى.', 'هغه د شار د شور نه نفرت کوی، او خرکار ورسره نشته چې په دې باندې اواز وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33288, 'Job 39:8', 'Job', 39, 8, 'دا غرونو ته ځى چې دا يې د څرن زمکه شى، او هر يو شين بوټے د خوراک دپاره لټوى.', 'دا غرونو ته جی چې دا یې د چرن زمکه شی، او هر یو شین بوتے د خوراک دپاره لتوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33289, 'Job 39:9', 'Job', 39, 9, 'ولې ځنګلى غوَيے به تا پرېږدى چې کار ترېنه واخلى؟ هغه به ستا په اخور کښې شپه تېره کړى څۀ؟', 'ولې جنګلی غویے به تا پرېزدی چې کار ترېنه واخلی؟ هغه به ستا په اخور کشې شپه تېره کری چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33290, 'Job 39:10', 'Job', 39, 10, 'ولې تۀ يو ځنګلى غوَيے د يوې دپاره تړلے شې؟ دا به ستا دپاره يو پټے يوه کړى څۀ؟', 'ولې تۀ یو جنګلی غویے د یوې دپاره ترلے شې؟ دا به ستا دپاره یو پتے یوه کری چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33291, 'Job 39:11', 'Job', 39, 11, 'ولې تۀ د هغې لوئ طاقت باندې اعتبار کولے شې چې هغه به ستا مدد وکړى؟ تۀ په دې باندې دا يقين کولے شې څۀ چې دا به ستا دپاره کار وکړى؟', 'ولې تۀ د هغې لوی طاقت باندې اعتبار کولے شې چې هغه به ستا مدد وکری؟ تۀ په دې باندې دا یقین کولے شې چۀ چې دا به ستا دپاره کار وکری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33292, 'Job 39:12', 'Job', 39, 12, 'تۀ په دې يقين کوې چې دا به واپس راشى، او ستا درمند ته به ګېډى راوړى؟', 'تۀ په دې یقین کوې چې دا به واپس راشی، او ستا درمند ته به ګېدی راوری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33293, 'Job 39:13', 'Job', 39, 13, 'د شتر‌مرغ وزر ښائسته کولاو خوريږى، خو دا د زاڼې د وزرو برابر کېدے خو نۀ شى.', 'د شتر‌مرغ وزر شایسته کولاو خوریزی، خو دا د زانې د وزرو برابر کېدے خو نۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33294, 'Job 39:14', 'Job', 39, 14, 'شتر‌مرغ خپلې هګۍ د دې دپاره په زمکه پرېږدى، چې ګرمى شى،', 'شتر‌مرغ خپلې هګی د دې دپاره په زمکه پرېزدی، چې ګرمی شی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33295, 'Job 39:15', 'Job', 39, 15, 'دا فکر نۀ کوى چې د څۀ پښې لاندې به راشى، او چې يو ځنګلى ځناور به يې ذرې ذرې کړى.', 'دا فکر نۀ کوی چې د چۀ پشې لاندې به راشی، او چې یو جنګلی جناور به یې ذرې ذرې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33296, 'Job 39:16', 'Job', 39, 16, 'دا په خپل بچى باندې داسې ظلم کوى، چې ګنې دا يې خپل نۀ وى، او کۀ مرى نو پرواه يې نۀ ساتى،', 'دا په خپل بچی باندې داسې ظلم کوی، چې ګنې دا یې خپل نۀ وی، او کۀ مری نو پرواه یې نۀ ساتی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_39_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
